mapper.select:
select category_id, parent_id, category_name, order_num, status
from edu_library_category
where category_id = #{categoryId}

select c.category_id, c.parent_id, c.category_name, c.order_num, c.status, (select count(1) from edu_library_document d where d.category_id = c.category_id and d.del_flag = '0') as doc_count from edu_library_category c
and c.category_name like ('%' || #{categoryName} || '%') and c.status = #{status}
order by c.order_num, c.category_id

mapper.update:
update edu_library_category
parent_id = #{parentId}, category_name = #{categoryName}, order_num = #{orderNum}, status = #{status},
where category_id = #{categoryId}
